        "facts": {
            "de": ["Buzău-Tal."],
            "hu": ["Bodza-völgy."],
            "ro": ["Valea Buzăului."],
            "en": ["Buzău Valley."]
        },
        "descriptionAdvanced": {
            "de": "Întorsura Buzăului, im Deutschen als Bodzau bekannt, ist eine Stadt im Kreis Covasna, die landesweit als einer der 'Pole der Kälte' in Rumänien berühmt ist. Geografisch liegt sie in einer malerischen Senke am Oberlauf des Flusses Buzău, umgeben von den Bergen der Ostkarpaten. Die Stadt verdankt ihren Namen einer scharfen Wendung ('Întorsura'), die der Fluss Buzău hier macht. Aufgrund ihrer hohen Lage und der topografischen Kessellage werden hier im Winter regelmäßig die tiefsten Temperaturen des Landes gemessen, was der Stadt einen besonderen Platz in der rumänischen Meteorologie einräumt. Trotz des rauen Klimas ist die Region von einer herzlichen Gemeinschaft und einer starken ländlichen Tradition geprägt. Die Umgebung bietet spektakuläre Landschaften für Naturliebhaber und Wanderer, insbesondere in den nahegelegenen Ciucaș-Bergen. Întorsura Buzăului ist ein Ort für Abenteurer, die die authentische Wildnis der Karpaten und die Ruhe abseits der großen Städte suchen.",
            "hu": "",
            "ro": "",
            "en": ""
        },
        "factsAdvanced": {
            "de": [
                "In Întorsura Buzăului werden im Winter oft Temperaturen unter -30 Grad Celsius gemessen.",
                "Der Name der Stadt bezieht sich auf die 180-Grad-Wende des Flusses Buzău in diesem Gebiet.",
                "Die Stadt liegt auf einer durchschnittlichen Höhe von etwa 750 Metern über dem Meeresspiegel.",
                "In der Nähe befindet sich das Naturschutzgebiet 'Valea Zimbrilor', wo Wisente in freier Natur beobachtet werden können.",
                "Die Stadt ist bekannt für ihre traditionellen Winterfeste, die den rauen Bedingungen trotzen.",
                "Die Forstwirtschaft und Viehzucht sind die wichtigsten wirtschaftlichen Pfeiler der Region.",
                "Întorsura Buzăului ist ein Tor zum Ciucaș-Massiv, bekannt für seine bizarren Felsformationen.",
                "Die Bevölkerung pflegt einen einzigartigen Dialekt, der Einflüsse aus Siebenbürgen und der Walachei vereint."
            ],
            "hu": [],
            "ro": [],
            "en": []
        }
