        "descriptionAdvanced": {
            "de": "Pașcani ist eine bedeutende Industriestadt im Kreis Iași, die landesweit als einer der wichtigsten Eisenbahnknotenpunkte der Region Moldau bekannt ist. Die Entwicklung der Stadt ist untrennbar mit dem Bau der ersten Eisenbahnlinien in der Moldau im 19. Jahrhundert verbunden, was Pașcani zu einem Zentrum für Schienenlogistik und Maschinenbau machte. Geografisch liegt die Stadt malerisch im Siret-Tal, umgeben von fruchtbarem Ackerland und sanften Hügeln. Pașcani hat sich in den letzten Jahrzehnten zu einem modernen urbanen Zentrum entwickelt, das neben der Industrie auch im Bildungs- und Kulturbereich eine wichtige regionale Rolle einnimmt. Die Architektur zeigt eine Mischung aus funktionalen Industriebauten und modernen Wohnvierteln. Ein besonderes Wahrzeichen ist der Cantacuzino-Pașcanu-Palast, der an die aristokratische Vergangenheit der Region erinnert. Pașcani ist ein Ort, der den Stolz der moldauischen Arbeiterklasse mit einer dynamischen Vision für die Zukunft verbindet.",
            "hu": "",
            "ro": "",
            "en": ""
        },
        "factsAdvanced": {
            "de": [
                "Pașcani wurde im Jahr 1419 erstmals in einem Dokument des Fürsten Alexander des Guten erwähnt.",
                "Die Stadt beherbergt große Werkstätten für die Reparatur von Schienenfahrzeugen (Remar).",
                "Pașcani liegt am rechten Ufer des Flusses Siret auf einer Höhe von etwa 250 Metern.",
                "Die Stadt erhielt im Jahr 1995 den Status eines Munizipiums.",
                "Der Cantacuzino-Pașcanu-Palast ist ein bedeutendes architektonisches Denkmal aus dem 17. Jahrhundert.",
                "Pașcani ist ein wichtiger Umsteigepunkt für Reisende in Richtung Suceava und Iași.",
                "In der Stadt gibt es eine starke Tradition in der Textil- und Lebensmittelindustrie.",
                "Jährlich findet in Pașcani ein überregional bekanntes Theaterfestival statt."
            ],
            "hu": [],
            "ro": [],
            "en": []
        }
