        "facts": {
            "de": ["Bogdana-Kloster."],
            "hu": ["Bogdana-kolostor."],
            "ro": ["Mănăstirea Bogdana."],
            "en": ["Bogdana Monastery."]
        },
        "descriptionAdvanced": {
            "de": "Rădăuți, im Deutschen Radautz, ist eine der faszinierendsten Städte der Bukowina und ein bedeutendes Zentrum für Geschichte und Tradition. Die Stadt war eine der ersten Residenzen der moldauischen Fürsten, wovon das Bogdana-Kloster zeugt, die älteste erhaltene Steinkirche der Moldau und Grablege der frühen Herrscher. Rădăuți strahlt ein unverwechselbares mitteleuropäisches Flair aus, geprägt durch die Zeit unter habsburgischer Verwaltung, was sich in der Architektur des Stadtzentrums und den breiten Alleen widerspiegelt. Geografisch liegt die Stadt in einer fruchtbaren Ebene am Fuße der Karpaten und dient als wichtiges Tor zu den berühmten bemalten Klöstern der Bukowina. Die Stadt ist zudem für ihr reiches Handwerk, insbesondere die Keramikherstellung und den Pferdemarkt, bekannt. Kulturell ist Rădăuți ein Schmelztiegel, in dem rumänische, deutsche und jüdische Einflüsse ein einzigartiges Erbe hinterlassen haben. Besucher schätzen die bürgerliche Eleganz, die historische Tiefe und die sprichwörtliche bukowiner Gastfreundschaft der Stadt.",
            "hu": "",
            "ro": "",
            "en": ""
        },
        "factsAdvanced": {
            "de": [
                "Rădăuți wurde erstmals im Jahr 1392 urkundlich erwähnt.",
                "Das Bogdana-Kloster beherbergt die Gräber der ersten moldauischen Fürsten, darunter Bogdan I.",
                "Die Stadt war im 19. Jahrhundert ein bedeutendes Zentrum des österreichisch-ungarischen Militärs (Landshauptstadt der Bukowina).",
                "Das Gestüt Rădăuți ist eines der ältesten und bedeutendsten in Rumänien, berühmt für die Shagya-Araber.",
                "In Rădăuți befindet sich das Ethnographische Museum 'Samuil și Eugenia Ioneț', eines der besten der Region.",
                "Die jüdische Gemeinde prägte historisch das Stadtbild durch die prächtige Große Synagoge (1883).",
                "Die Stadt liegt auf einer Höhe von 375 Metern über dem Meeresspiegel.",
                "Rădăuți ist bekannt für seine traditionsreiche Keramikmanufaktur (Colibaba Keramik)."
            ],
            "hu": [],
            "ro": [],
            "en": []
        }
